fn fibonacci(n: usize) -> Vec<i32> {
    // Precondition: n >= 2
    // Allocate a Vec with capacity n
    let mut fibs = Vec::with_capacity(n);

    // Base cases
    fibs.push(0);
    fibs.push(1);

    // Compute subsequent Fibonacci numbers iteratively
    for i in 2..n {
        let next = fibs[i - 1] + fibs[i - 2];
        fibs.push(next);
    }

    fibs
}